-- =====================================================================
-- V1.4.3 DDL：新增 数据管理 - API 接入表 model_data_api
-- 对应后端：ModelDataApiDO / ModelDataApiMapper.xml
-- 注：model_calc / model_config 表本次不改动（resourceId、outputSchema 已存在）
-- =====================================================================

DROP TABLE IF EXISTS `model_data_api`;
CREATE TABLE `model_data_api` (
    `id`                  bigint(20)      NOT NULL AUTO_INCREMENT COMMENT 'ID',
    `name`                varchar(128)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'API数据名称',
    `model_id`            bigint(20)      NULL DEFAULT NULL COMMENT '关联模型ID',
    `api_type`            varchar(64)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'API类型（字典 model_data_api_type）',
    `api_url`             varchar(512)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接口地址',
    `request_method`      varchar(16)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'POST' COMMENT '请求方式（字典 model_access_mode）',
    `content_type`        varchar(64)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'application/json' COMMENT '请求内容类型（字典 content_type）',
    `timeout_seconds`     bigint(20)      NULL DEFAULT 30 COMMENT '超时时间（秒）',

    `auth_type`           varchar(32)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'NONE' COMMENT '鉴权类型：NONE/FIXED/DYNAMIC（字典 auth_type）',
    `auth_method`         varchar(32)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鉴权方式：apiKey/bearer',
    `auth_inject_pos`     varchar(32)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '注入位置：header/query（字典 auth_inject_position）',
    `auth_key_name`       varchar(128)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '鉴权键名',
    `auth_token_prefix`   varchar(64)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Token 前缀',
    `auth_token_value`    varchar(512)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '固定 Token 值 / APIKey',

    `auth_dyn_method`     varchar(16)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '动态获取 Token 方式',
    `auth_dyn_url`        varchar(512)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '动态获取 Token 地址',
    `auth_dyn_headers`    text            CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '动态获取 Token 请求头(JSON)',
    `auth_dyn_params`     text            CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '动态获取 Token Query 参数(JSON)',
    `auth_dyn_body`       text            CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '动态获取 Token 请求体(JSON)',
    `auth_extract_path`   varchar(128)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'Token 提取路径（JSONPath）',

    `request_template`    longtext        CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '请求参数模板',
    `batch_params`        longtext        CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '批量请求参数',
    `input_schema`        longtext        CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '入参 JSON Schema 定义',
    `output_schema`       longtext        CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '出参 JSON Schema 定义',
    `description`         varchar(512)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '描述',

    `valid_flag`          tinyint(1)      NOT NULL DEFAULT 1 COMMENT '是否有效：0-无效，1-有效',
    `del_flag`            tinyint(1)      NOT NULL DEFAULT 0 COMMENT '删除标志：0-未删除，1-已删除',

    `create_by`           varchar(32)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
    `creator_id`          bigint(20)      NULL DEFAULT NULL COMMENT '创建人ID',
    `create_time`         datetime        NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
    `update_by`           varchar(32)     CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
    `updater_id`          bigint(20)      NULL DEFAULT NULL COMMENT '更新人ID',
    `update_time`         datetime        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
    `remark`              varchar(512)    CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',

    PRIMARY KEY (`id`) USING BTREE,
    INDEX `idx_mda_model_id`     (`model_id`)     USING BTREE,
    INDEX `idx_mda_name`         (`name`)         USING BTREE,
    INDEX `idx_mda_create_time`  (`create_time`)  USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '模型数据API接入表' ROW_FORMAT = Dynamic;

INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (1, '水文站实时水位监测接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/waterLevel', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"station_code\":{\"type\":\"string\",\"description\":\"水文站编码\",\"example\":\"HT-6201\"}}}', '{\"type\":\"object\",\"properties\":{\"station_code\":{\"type\":\"string\",\"description\":\"水文站编码\"},\"water_level\":{\"type\":\"number\",\"description\":\"实时水位(米)\"},\"flow\":{\"type\":\"number\",\"description\":\"实时流量(m³/s)\"},\"warn_level\":{\"type\":\"number\",\"description\":\"警戒水位(米)\"},\"rainfall\":{\"type\":\"number\",\"description\":\"流域降雨量(mm)\"},\"monitor_time\":{\"type\":\"string\",\"description\":\"监测时间\"}}}', '实时回传水文站水位、流量、降雨等特征，供水位/水量预测模型按名称匹配入参', 1, 0, '吴桐', 1, '2026-10-20 10:05:00', '吴桐', NULL, '2026-10-29 17:47:40', '水文站实时水位在线监测接口，回传水位、流量、降雨等特征，水位/水量预测模型按名称自动匹配入参');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (2, '气象观测数据获取接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/weather', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"city\":{\"type\":\"string\",\"description\":\"城市名称\",\"example\":\"南京\"}}}', '{\"type\":\"object\",\"properties\":{\"city\":{\"type\":\"string\",\"description\":\"城市名称\"},\"temperature\":{\"type\":\"number\",\"description\":\"气温(℃)\"},\"humidity\":{\"type\":\"number\",\"description\":\"相对湿度(%)\"},\"rainfall\":{\"type\":\"number\",\"description\":\"降雨量(mm)\"},\"wind_speed\":{\"type\":\"number\",\"description\":\"风速(m/s)\"},\"pressure\":{\"type\":\"number\",\"description\":\"气压(hPa)\"}}}', '第三方气象接口，获取气温、降雨、风速等特征，补充预报类模型输入', 1, 0, '吴同', 2, '2026-10-20 10:12:00', '吴桐', NULL, '2026-10-29 17:47:41', '第三方气象接口，获取气温、降雨、风速等数据，补充预报类模型输入特征');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (3, '设备健康度评估接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/deviceHealth', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"device_id\":{\"type\":\"string\",\"description\":\"设备编号\",\"example\":\"PUMP-03\"}}}', '{\"type\":\"object\",\"properties\":{\"device_id\":{\"type\":\"string\",\"description\":\"设备编号\"},\"health_score\":{\"type\":\"number\",\"description\":\"健康度评分\"},\"vibration\":{\"type\":\"number\",\"description\":\"振动值(mm/s)\"},\"bearing_temp\":{\"type\":\"number\",\"description\":\"轴承温度(℃)\"},\"runtime_hours\":{\"type\":\"integer\",\"description\":\"累计运行时长(h)\"},\"fault_prob\":{\"type\":\"number\",\"description\":\"故障概率\"}}}', '设备物联数据接口，输出健康度、振动、温度等特征，供预测性维护模型使用', 1, 0, '吴桐', 1, '2026-10-20 10:20:00', '吴桐', NULL, '2026-10-29 17:47:44', '设备物联监测接口，返回健康度、振动、轴温等特征，供预测性维护模型调用');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (4, '电力负荷预测接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/powerLoad', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"region\":{\"type\":\"string\",\"description\":\"供区名称\",\"example\":\"工业园区-A\"}}}', '{\"type\":\"object\",\"properties\":{\"region\":{\"type\":\"string\",\"description\":\"供区名称\"},\"load_value\":{\"type\":\"number\",\"description\":\"实时负荷(kW)\"},\"peak_load\":{\"type\":\"number\",\"description\":\"峰值负荷(kW)\"},\"voltage\":{\"type\":\"number\",\"description\":\"电压(V)\"},\"current\":{\"type\":\"number\",\"description\":\"电流(A)\"},\"power_factor\":{\"type\":\"number\",\"description\":\"功率因数\"}}}', '电网负荷特征接口，回传实时/峰值负荷及电气量，供负荷预测模型匹配入参', 1, 0, '吴同', 2, '2026-10-20 10:28:00', '吴桐', NULL, '2026-10-29 17:47:49', '电网负荷采集接口，回传实时/峰值负荷及电压电流等电气量，供负荷预测模型匹配入参');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (5, '交通流量监测接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/trafficFlow', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"road_id\":{\"type\":\"string\",\"description\":\"路段编号\",\"example\":\"G42-108\"}}}', '{\"type\":\"object\",\"properties\":{\"road_id\":{\"type\":\"string\",\"description\":\"路段编号\"},\"vehicle_count\":{\"type\":\"integer\",\"description\":\"断面车流量(辆)\"},\"avg_speed\":{\"type\":\"number\",\"description\":\"平均车速(km/h)\"},\"congestion_index\":{\"type\":\"number\",\"description\":\"拥堵指数\"},\"lane_occupancy\":{\"type\":\"number\",\"description\":\"车道占有率\"}}}', '路网交通检测接口，输出车流量、车速、拥堵指数，供交通流预测模型使用', 1, 0, '吴桐', 1, '2026-10-20 10:35:00', '吴桐', NULL, '2026-10-29 17:47:50', '路网断面检测接口，返回车流量、车速、拥堵指数，供交通流预测模型使用');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (6, '空气质量监测接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/airQuality', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"station_name\":{\"type\":\"string\",\"description\":\"监测点名称\",\"example\":\"城南监测点\"}}}', '{\"type\":\"object\",\"properties\":{\"station_name\":{\"type\":\"string\",\"description\":\"监测点名称\"},\"aqi\":{\"type\":\"integer\",\"description\":\"综合空气质量指数\"},\"pm25\":{\"type\":\"number\",\"description\":\"PM2.5(μg/m³)\"},\"pm10\":{\"type\":\"number\",\"description\":\"PM10(μg/m³)\"},\"so2\":{\"type\":\"number\",\"description\":\"SO₂(μg/m³)\"},\"no2\":{\"type\":\"number\",\"description\":\"NO₂(μg/m³)\"},\"o3\":{\"type\":\"number\",\"description\":\"O₃(μg/m³)\"}}}', '环境监测接口，回传各项污染物浓度与 AQI，供空气质量预测模型匹配入参', 1, 0, '吴同', 2, '2026-10-20 10:42:00', '吴桐', NULL, '2026-10-29 17:47:50', '环境空气质量监测接口，回传PM2.5、PM10等污染物浓度与AQI，供空气质量预测模型使用');
INSERT INTO `model_data_api` (`id`, `name`, `model_id`, `api_type`, `api_url`, `request_method`, `content_type`, `timeout_seconds`, `auth_type`, `auth_method`, `auth_inject_pos`, `auth_key_name`, `auth_token_prefix`, `auth_token_value`, `auth_dyn_method`, `auth_dyn_url`, `auth_dyn_headers`, `auth_dyn_params`, `auth_dyn_body`, `auth_extract_path`, `request_template`, `batch_params`, `input_schema`, `output_schema`, `description`, `valid_flag`, `del_flag`, `create_by`, `creator_id`, `create_time`, `update_by`, `updater_id`, `update_time`, `remark`) VALUES (7, '信贷风险评估接口', NULL, NULL, 'https://demo.qmodel.tech/prod-api/model/mock/creditRisk', '0', 'application/json', 30, 'NONE', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{\"type\":\"object\",\"properties\":{\"applicant_id\":{\"type\":\"string\",\"description\":\"申请人编号\",\"example\":\"USR-20886\"}}}', '{\"type\":\"object\",\"properties\":{\"applicant_id\":{\"type\":\"string\",\"description\":\"申请人编号\"},\"credit_score\":{\"type\":\"integer\",\"description\":\"信用评分\"},\"risk_level\":{\"type\":\"string\",\"description\":\"风险等级\"},\"debt_ratio\":{\"type\":\"number\",\"description\":\"负债率\"},\"overdue_count\":{\"type\":\"integer\",\"description\":\"历史逾期次数\"}}}', '风控数据接口，输出信用评分、负债率等特征，供违约预测模型使用', 1, 0, '吴桐', 1, '2026-10-20 10:50:00', '吴桐', NULL, '2026-10-29 17:47:52', '信贷风控数据接口，返回信用评分、负债率、逾期次数等特征，供违约预测模型调用');
